// swift-tools-version:5.9
// macOS app (SwiftUI) on top of the Rust core `eqing_core`.
// The static library and the uniFFI bindings are produced by scripts/build_mac.sh.
import PackageDescription
import Foundation

let here = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
let libDir = here.appendingPathComponent("lib").path

let package = Package(
    name: "EQingFactory",
    platforms: [.macOS(.v14)],
    targets: [
        // C header and module map generated by uniFFI (link "eqing_core")
        .systemLibrary(name: "eqing_coreFFI", path: "Sources/eqing_coreFFI"),
        .executableTarget(
            name: "EQingFactory",
            dependencies: ["eqing_coreFFI"],
            path: "Sources/EQingFactory",
            linkerSettings: [
                .unsafeFlags(["-L", libDir]),
                .linkedFramework("CoreFoundation"),
                .linkedFramework("Security"),
                .linkedLibrary("iconv"),
            ]
        ),
    ]
)
